#include <cstdlib>
#include <iostream>
#include <vector>

int n;
std::vector<int> col;

bool safe(int row, int c) {
    for (int r = 0; r < row; ++r)
        if (col[r] == c || std::abs(row - r) == std::abs(c - col[r])) return false;
    return true;
}

long long place(int row) {
    if (row == n) return 1;
    long long total = 0;
    for (int c = 0; c < n; ++c)
        if (safe(row, c)) { col[row] = c; total += place(row + 1); }   // prune here
    return total;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    std::cin >> n;
    col.assign(n, 0);
    std::cout << place(0) << '\n';
}
